# The FULL structural ancestor path (purely from the static GROUPS shape,
# no data involved) plus, when `name` itself names a group, that group's own
# node appended last — same meaning as scraper_grouped.py.j2's identical
# helper. Which of these ancestors actually turn out to be repeating is
# resolved separately, dynamically, by _blueprint_resolve_leaf_chain below.
def _blueprint_full_path(name):
    ancestors = _BLUEPRINT_PATH_BY_NAME.get(name, [])
    group = _BLUEPRINT_GROUP_BY_NAME.get(name)
    return ancestors + [group] if group is not None else ancestors


def _blueprint_walk_suffix(scopes, suffix):
    for group in suffix:
        next_scopes = []
        for scope in scopes:
            next_scopes.extend(_resolve_items(scope, group["path"]))
        scopes = next_scopes
    return scopes


# Walks `suffix` from `scope` one group at a time — using the first resolved
# instance to continue deeper, the same "resolved once, applies globally"
# pragmatism BLUEPRINT_MAPPING's own runtime chain resolution already
# accepts — returning the names among `suffix` that resolved as repeating.
# The dynamic, per-scope counterpart of scraper_grouped.py.j2's static
# _blueprint_repeating_chain lookup.
def _blueprint_resolve_leaf_chain(scope, suffix):
    chain = []
    current = scope
    for group in suffix:
        raw = _resolve_json_path(current, group["path"])
        if raw and all(isinstance(v, list) for v in raw):
            chain.append(group["name"])
        instances = _resolve_items(current, group["path"])
        if not instances:
            break
        current = instances[0]
    return chain


# Resolves this target group's own row scope exactly like
# scraper_grouped.py.j2's own _blueprint_resolve_group_chain — the deepest
# repeating source ancestor its direct leaf fields agree on, falling back to
# ancestor_chain when none of them add further nesting — but, unlike that
# static version, actually walks `scope` to find out, and raises on
# conflict instead of trusting a generate-time guarantee that doesn't exist
# for this shape (see this section's own doc comment above).
def _blueprint_resolve_group_chain(scope, ancestor_chain, ancestor_full_path, target_children):
    chains = []
    for source_name in (c["source"] for c in target_children if "source" in c):
        suffix = _blueprint_full_path(source_name)[len(ancestor_full_path):]
        chains.append(ancestor_chain + _blueprint_resolve_leaf_chain(scope, suffix))

    deeper = [c for c in chains if len(c) > len(ancestor_chain)]
    if not deeper:
        return ancestor_chain

    winner = max(deeper, key=len)
    for chain in deeper:
        if not (len(chain) <= len(winner) and winner[:len(chain)] == chain):
            raise RuntimeError(
                "Output Blueprint: the mapped fields under one target group span more than one independent "
                f"repeating group ('{chain[-1]}' and '{winner[-1]}' are not on the same nesting path) — there "
                "is no single row layout that would include every mapped field without either duplicating "
                "rows or dropping data. Nest them under separate target groups instead."
            )
    return winner


# See scraper_grouped.py.j2's identical-in-spirit _build_blueprint_node for
# the full design reasoning (list for a target group, single Element for a
# target leaf; `top_scope` resolves a "broadcast" field — one with no
# repeating source ancestor anywhere in its lineage — independently of the
# current recursion depth). Issue #206 note: same as
# _flatten_api_group_for_blueprint above — no sibling element to resolve a
# combineFields/splitField transform against here.
def _build_blueprint_node(top_scope, scope, ancestor_chain, ancestor_full_path, target_node):
    if "children" in target_node:
        row_chain = _blueprint_resolve_group_chain(scope, ancestor_chain, ancestor_full_path, target_node["children"])
        full_path = _blueprint_full_path(row_chain[-1]) if row_chain else ancestor_full_path
        instances = _blueprint_walk_suffix([scope], full_path[len(ancestor_full_path):])

        elements = []
        for instance in instances:
            el = ET.Element(target_node["name"])
            for child in target_node["children"]:
                result = _build_blueprint_node(top_scope, instance, row_chain, full_path, child)
                if isinstance(result, list):
                    el.extend(result)
                else:
                    el.append(result)
            elements.append(el)
        return elements

    source_name = target_node["source"]
    leaf_node = _BLUEPRINT_LEAF_BY_NAME[source_name]
    full_path = _blueprint_full_path(source_name)
    global_chain = _blueprint_resolve_leaf_chain(top_scope, full_path)
    if global_chain:
        scopes = _blueprint_walk_suffix([scope], full_path[len(ancestor_full_path):])
    else:
        # Broadcast: this field has no repeating source ancestor anywhere in
        # its lineage, so it's resolved relative to the whole response, not
        # wherever the current target group instance happens to be.
        scopes = _blueprint_walk_suffix([top_scope], full_path)

    resolved = scopes[0] if scopes else None
    value = None if resolved is None else _resolve_field(resolved, leaf_node["path"])
    el = ET.Element(target_node["name"])
    el.text = "" if value is None else _apply_transforms(str(value), leaf_node["transform"])
    return el


def _build_blueprint_tree(top_scope, target_roots):
    elements = []
    for target_node in target_roots:
        result = _build_blueprint_node(top_scope, top_scope, [], [], target_node)
        if isinstance(result, list):
            elements.extend(result)
        else:
            elements.append(result)
    return elements






_PATH_TOKEN_PATTERN = re.compile(r"[^.\[\]]+|\[\*\]|\[\d+\]")


# Minimal JSON-path DSL: dot-notation for object keys, "[*]" to flatten into
# every element of an array, "[n]" for a specific index. Returns every match
# as a flat list — a bare key/index yields at most one, but "[*]" can yield
# several, which is what lets one path (e.g. "results[*].items") reach into
# more than one array at once.
def _resolve_json_path(data, path):
    values = [data]
    for token in _PATH_TOKEN_PATTERN.findall(path):
        next_values = []
        if token == "[*]":
            for value in values:
                if isinstance(value, list):
                    next_values.extend(value)
        elif token.startswith("["):
            index = int(token[1:-1])
            for value in values:
                if isinstance(value, list) and -len(value) <= index < len(value):
                    next_values.append(value[index])
        else:
            for value in values:
                if isinstance(value, dict) and token in value:
                    next_values.append(value[token])
        values = next_values
    return values


# A group's Path is expected to resolve to "the list of instances", however
# it gets there — a path ending on the list itself (values == [the_list]) and
# a path that already fans out via "[*]" (values == [list_a, list_b, ...])
# both end up as one or more list matches, so flattening them one level
# always produces the intended flat instance list either way. An empty Path
# ("" — see ApiGroup.Path) resolves to values == [scope]: if scope itself is
# a list this still flattens it (the "two directly-nested repeating levels
# with no key between them" case), otherwise scope is treated as the single
# instance.
def _resolve_items(data, path):
    values = _resolve_json_path(data, path)
    if values and all(isinstance(value, list) for value in values):
        return [item for sublist in values for item in sublist]
    return values


def _resolve_field(record, path):
    values = _resolve_json_path(record, path)
    return values[0] if values else None


# Issue #84: best-effort numeric normalization for a "toNumber" transform —
# finds the first numeric-looking substring and normalizes its decimal
# separator to '.', stripping thousands separators/currency symbols. When
# both '.' and ',' appear, the rightmost one is treated as the decimal point
# (handles both "1.234,56" and "1,234.56"); a single separator appearing more
# than once is treated as a thousands separator and stripped; a single
# separator appearing exactly once is treated as the decimal point (so
# "12,99"/"12.99" both work, at the cost of a genuinely ambiguous
# single-occurrence case like "1.234" always being read as 1.234, never as
# 1234 — chain a regex-extract transform first if that's not what's wanted).
# Empty string if nothing numeric is found.
def _to_number(value):
    match = re.search(r"-?\d[\d.,]*", value)
    if not match:
        return ""
    raw = match.group(0)
    last_dot = raw.rfind(".")
    last_comma = raw.rfind(",")
    if last_dot != -1 and last_comma != -1:
        decimal_pos = max(last_dot, last_comma)
        integer_part = raw[:decimal_pos].replace(".", "").replace(",", "")
        fractional_part = raw[decimal_pos + 1:]
        normalized = f"{integer_part}.{fractional_part}"
    elif raw.count(",") > 1 or raw.count(".") > 1:
        normalized = raw.replace(",", "").replace(".", "")
    else:
        normalized = raw.replace(",", ".")
    try:
        numeric = float(normalized)
    except ValueError:
        return ""
    return str(int(numeric)) if numeric.is_integer() else str(numeric)


# Issue #205: safe, explicit type-conversion transforms -- unlike toNumber's
# best-effort heuristic extraction, these either produce a well-formed value
# or fall back to their own clearly defined "onError" behavior
# ("KeepOriginal" leaves the pre-conversion value untouched, "UseDefault"
# substitutes the transform's own configured "defaultValue") rather than
# silently guessing.
_DATE_FORMAT_TOKEN_PATTERNS = {"yyyy": r"(?P<yyyy>\d{4})", "mm": r"(?P<mm>\d{1,2})", "dd": r"(?P<dd>\d{1,2})"}


def _type_conversion_fallback(value, on_error, default_value):
    return default_value if on_error == "UseDefault" else value


def _to_integer(value, on_error, default_value):
    stripped = value.strip()
    if re.fullmatch(r"[+-]?\d+", stripped):
        return str(int(stripped))
    return _type_conversion_fallback(value, on_error, default_value)


def _to_boolean(value, on_error, default_value):
    normalized = value.strip().lower()
    if normalized in ("true", "1", "yes", "y"):
        return "True"
    if normalized in ("false", "0", "no", "n"):
        return "False"
    return _type_conversion_fallback(value, on_error, default_value)


# source_format is the same "{yyyy}"/"{mm}"/"{dd}" mini-template
# RangeSource.Format (RangeFormat.cs) already uses for ISO week/date
# parameters, compiled into a regex the same way (escape the literal
# template, then substitute each placeholder for its own capture group) so a
# format string valid on the companion side parses identically here. Also
# rejects a structurally-matching but non-existent calendar date (e.g.
# "2026-02-30") via date()'s own ValueError, not just a pattern match.
def _to_date(value, source_format, on_error, default_value):
    pattern = re.escape(source_format)
    for token, token_pattern in _DATE_FORMAT_TOKEN_PATTERNS.items():
        pattern = pattern.replace(re.escape("{" + token + "}"), token_pattern)
    match = re.fullmatch(pattern, value.strip())
    if match:
        try:
            return date(int(match.group("yyyy")), int(match.group("mm")), int(match.group("dd"))).isoformat()
        except ValueError:
            pass
    return _type_conversion_fallback(value, on_error, default_value)


# Issue #234: strict price/currency conversion. number_format is one of
# ToCurrencyTransform.SupportedFormats, each written as its own example
# amount — its first punctuation mark is the thousands separator, its last
# the decimal separator (a space format also accepts no-break/narrow
# no-break spaces, the apostrophe format a typographic apostrophe). Finds
# the first number in the value (a separator only counts when a digit
# follows, so a trailing "." or "," after the amount is never swallowed),
# requires it to match the format strictly (thousands groups of exactly
# three digits, at most one decimal separator), and keeps the fraction
# digits exactly as scraped — no float rounding. Mirrored by
# toCurrencyPreview in extension/popup/field-transforms.js.
_CURRENCY_FORMATS = {
    "1.234,56": (",", "."),
    "1,234.56": (".", ","),
    "1 234,56": (",", "   "),
    "1'234.56": (".", "'’"),
}


def _to_currency(value, number_format, on_error, default_value):
    decimal_sep, thousands_seps = _CURRENCY_FORMATS.get(number_format, _CURRENCY_FORMATS["1.234,56"])
    candidate = re.search(r"[+-]?[0-9](?:[0-9]|[" + re.escape(decimal_sep + thousands_seps) + r"](?=[0-9]))*", value)
    if candidate:
        thousands = "[" + re.escape(thousands_seps) + "]"
        match = re.fullmatch(
            r"([+-]?)([0-9]{1,3}(?:" + thousands + r"[0-9]{3})+|[0-9]+)(?:" + re.escape(decimal_sep) + r"([0-9]+))?",
            candidate.group(0),
        )
        if match:
            integer = str(int(re.sub(thousands, "", match.group(2))))
            sign = "-" if match.group(1) == "-" else ""
            return sign + integer + ("." + match.group(3) if match.group(3) else "")
    return _type_conversion_fallback(value, on_error, default_value)


# Applies a field's ordered transform chain — each step's output feeds the
# next step's input, in the order the user configured them in.
# Issue #206: looks up another field's own already-computed value for
# CombineFieldsTransform/SplitFieldTransform. `siblings` is whatever
# representation the calling shape already has on hand at this point in
# extraction — a plain dict for flat/API-flat mode's in-progress row, or the
# in-construction parent ET.Element for container/API-tree mode (only that
# element's own direct children are considered, i.e. only siblings under the
# very same immediate parent group — see ScrapingPlanValidator's
# ValidateFieldTransformOrdering for why this is guaranteed to already be
# populated for a valid config). Missing/not-yet-computed simply resolves to
# "" rather than raising, the same "don't fail the whole row/element over
# one field" spirit every other transform here already follows.
def _resolve_transform_sibling(siblings, name):
    if siblings is None:
        return ""
    if isinstance(siblings, dict):
        return siblings.get(name, "")
    found = siblings.find(name)
    return (found.text or "") if found is not None else ""


def _apply_transforms(value, transforms, siblings=None):
    for t in transforms:
        kind = t["kind"]
        if kind == "trim":
            value = value.strip()
        elif kind == "regexExtract":
            match = re.search(t["pattern"], value)
            if match:
                try:
                    value = match.group(t.get("group", 0)) or ""
                except (IndexError, re.error):
                    value = ""
            else:
                value = ""
        elif kind == "replace":
            value = value.replace(t["find"], t["replacement"])
        elif kind == "toNumber":
            value = _to_number(value)
        elif kind == "toInteger":
            value = _to_integer(value, t.get("onError", "KeepOriginal"), t.get("defaultValue", ""))
        elif kind == "toBoolean":
            value = _to_boolean(value, t.get("onError", "KeepOriginal"), t.get("defaultValue", ""))
        elif kind == "toDate":
            value = _to_date(value, t.get("sourceFormat", "{yyyy}-{mm}-{dd}"), t.get("onError", "KeepOriginal"), t.get("defaultValue", ""))
        elif kind == "toCurrency":
            value = _to_currency(value, t.get("format", "1.234,56"), t.get("onError", "KeepOriginal"), t.get("defaultValue", ""))
        elif kind == "combineFields":
            value = t.get("separator", " ").join(_resolve_transform_sibling(siblings, n) for n in t.get("sourceFieldNames", []))
        elif kind == "splitField":
            parts = _resolve_transform_sibling(siblings, t.get("sourceFieldName", "")).split(t.get("separator", " "))
            idx = t.get("index", 0)
            value = parts[idx] if 0 <= idx < len(parts) else ""
    return value


_DEFAULT_ISO_WEEK_FORMAT = "{yyyy}-W{ww}"
_DEFAULT_DATE_FORMAT = "{yyyy}-{mm}-{dd}"

# "{token}" mini-template, mirrored token-for-token by the companion's
# RangeFormat (used to validate From/To ahead of a real script run) — the
# site's own URL convention decides which tokens/separators are needed
# (e.g. ISO-8601 "2026-W35" vs. a site using "2026-35"), so this is
# configurable per RangeSource instead of hardcoded to one format.
_RANGE_FORMAT_TOKEN_PATTERNS = {"yyyy": r"\d{4}", "ww": r"\d{1,2}", "mm": r"\d{1,2}", "dd": r"\d{1,2}"}


def _compile_range_format(fmt):
    pattern = re.escape(fmt)
    for token, value_pattern in _RANGE_FORMAT_TOKEN_PATTERNS.items():
        pattern = pattern.replace(re.escape("{" + token + "}"), f"(?P<{token}>{value_pattern})")
    return re.compile(f"^{pattern}$")


def _parse_range_value(value, fmt):
    match = _compile_range_format(fmt).match(value)
    if not match:
        raise ValueError(f"Value '{value}' does not match format '{fmt}'.")
    return {token: int(v) for token, v in match.groupdict().items()}


def _render_range_value(tokens, fmt):
    rendered = fmt
    for token, value in tokens.items():
        width = 4 if token == "yyyy" else 2
        rendered = rendered.replace("{" + token + "}", f"{value:0{width}d}")
    return rendered


# IsoWeek resolves "today" for *both* From and To (they share this parse
# step) — unlike Date below, where only To gets that treatment.
def _parse_iso_week(value, fmt):
    if value == "today":
        year, week, _ = datetime.date.today().isocalendar()
        return year, week
    tokens = _parse_range_value(value, fmt)
    return tokens["yyyy"], tokens["ww"]


def _iso_week_range(from_value, to_value, fmt):
    start_year, start_week = _parse_iso_week(from_value, fmt)
    end_year, end_week = _parse_iso_week(to_value, fmt)
    start_ordinal = datetime.date.fromisocalendar(start_year, start_week, 1).toordinal()
    end_ordinal = datetime.date.fromisocalendar(end_year, end_week, 1).toordinal()

    weeks = []
    ordinal = start_ordinal
    while ordinal <= end_ordinal:
        iso_year, iso_week, _ = datetime.date.fromordinal(ordinal).isocalendar()
        weeks.append(_render_range_value({"yyyy": iso_year, "ww": iso_week}, fmt))
        ordinal += 7
    return weeks


def _date_range(from_value, to_value, fmt):
    start_tokens = _parse_range_value(from_value, fmt)
    start = datetime.date(start_tokens["yyyy"], start_tokens["mm"], start_tokens["dd"])
    if to_value == "today":
        end = datetime.date.today()
    else:
        end_tokens = _parse_range_value(to_value, fmt)
        end = datetime.date(end_tokens["yyyy"], end_tokens["mm"], end_tokens["dd"])

    dates = []
    current = start
    while current <= end:
        dates.append(_render_range_value({"yyyy": current.year, "mm": current.month, "dd": current.day}, fmt))
        current += datetime.timedelta(days=1)
    return dates


def _number_range(from_value, to_value):
    return [str(n) for n in range(int(from_value), int(to_value) + 1)]


_URL_TEMPLATE_PLACEHOLDER_PATTERN = re.compile(r"\{([^{}]+)\}")


# Issue #217: a DiscoverySource/BrowserDiscoverySource may reference an
# earlier-declared parameter's own value via the same "{name}" placeholder
# syntax URL_TEMPLATE itself uses (e.g. a category-scoped discovery endpoint
# like ".../categories/{category}/weeks") — ScrapingPlanValidator already
# guarantees any such reference names an earlier parameter, never a later or
# self one, so by the time this parameter is being resolved every name it
# could possibly reference is already a key in `combo`. A placeholder naming
# something that isn't a resolved-so-far parameter at all (a typo, or simply
# not a reference this mechanism understands) is left untouched.
def _substitute_known_parameters(template, combo):
    def _replace(match):
        name = match.group(1)
        return quote(str(combo[name]), safe="") if name in combo else match.group(0)
    return _URL_TEMPLATE_PLACEHOLDER_PATTERN.sub(_replace, template)


# Resolving every parameter independently and then taking the full
# cartesian product (this function's only job before Issue #217) breaks
# down once a later parameter's own source can depend on an earlier one's
# value — that parameter's value list isn't one fixed list anymore, it's a
# different list per distinct combination of whatever it actually
# references. `cache` still resolves a parameter exactly once when it
# depends on nothing already resolved — every StaticListSource/RangeSource,
# and any Discovery/BrowserDiscovery source with no "{name}" reference to an
# earlier parameter — the same "resolve once, not once per combo" behavior
# this had before chaining existed, since a source with no such reference
# always maps to the same (empty) cache key regardless of `combo`.
def _resolve_parameter_combos(headers):
    combos = [{}]
    for parameter in PARAMETERS:
        name = parameter["name"]
        source = parameter["source"]
        new_combos = []
        cache = {}
        for combo in combos:
            kind = source.get("kind")
            if kind == "discovery":
                template = source.get("urlTemplate", "")
            elif kind == "browserDiscovery":
                template = source.get("discoveryUrl", "")
            else:
                template = ""
            referenced = set(_URL_TEMPLATE_PLACEHOLDER_PATTERN.findall(template)) & combo.keys()
            cache_key = tuple(sorted((ref_name, combo[ref_name]) for ref_name in referenced))
            if cache_key not in cache:
                cache[cache_key] = _resolve_parameter_values(source, headers, name, combo)
            for value in cache[cache_key]:
                new_combos.append({**combo, name: value})
        combos = new_combos
    return combos




# Turns a failed request into one clean, actionable error line (and a
# dedicated exit code) instead of a raw requests traceback — a 401/403 in
# particular almost always means missing or wrong authentication, which the
# message says outright, together with what to configure.
EXIT_REQUEST_FAILED = 7


def _display_url(url):
    return url


def _request_failed(what, url, detail):
    print(f"ERROR: {what} to {_display_url(url)} failed: {detail}", file=sys.stderr)
    sys.exit(EXIT_REQUEST_FAILED)


def _http_error_detail(status_code):
    if status_code in (401, 403):
        reason = "Unauthorized" if status_code == 401 else "Forbidden"
        return (f"HTTP {status_code} ({reason}). The API requires authentication that this configuration "
                f"doesn't send — adopt the recorded authentication header (e.g. Authorization) or enable the "
                f"auth bootstrap to fetch a fresh token before every run.")
    if status_code == 429:
        return "HTTP 429 (Too Many Requests). The API is rate-limiting this script — try again later."
    if status_code >= 500:
        return f"HTTP {status_code}. The API's server reported an error — this is usually temporary, try again later."
    return f"HTTP {status_code}."


def _checked_request(what, url, send):
    try:
        response = send()
    except requests.RequestException as e:
        _request_failed(what, url, f"could not reach the API ({e.__class__.__name__}).")
    return response


def _require_ok(what, url, response):
    if not response.ok:
        _request_failed(what, url, _http_error_detail(response.status_code))


def _json_or_fail(what, url, response):
    try:
        return response.json()
    except ValueError:
        _request_failed(what, url, f"the response is not JSON (Content-Type: {response.headers.get('Content-Type', 'unknown')}).")


def _build_headers():
    # Many sites (Wikipedia among them) reject the bare "python-requests/x.y"
    # default User-Agent with 403 Forbidden — an honest, identifying UA (not
    # a spoofed browser) is enough to pass that check on most sites. Set
    # first so a user-configured "User-Agent" header below still overrides
    # it (dict assignment order + requests' own case-insensitive header
    # handling means the later entry wins regardless of casing).
    headers = {"User-Agent": "Mozilla/5.0 (compatible; ScrapingFactory/1.0; +https://github.com/Aventinis/Scraping-Factory)"}
    for header in HEADERS:
        headers[header["name"]] = header["value"] if "value" in header else os.environ[header["envVar"]]
    return headers


# Discovery requests reuse the main HEADERS (e.g. an auth token) since a
# discovery endpoint is typically part of the same API as the main request.
# `combo` holds every earlier-declared parameter's own already-resolved
# value (Issue #217) — substituted into a discovery/browserDiscovery
# source's own template before it's used, so e.g. a category-scoped
# discovery endpoint resolves against this specific run's category.
def _resolve_parameter_values(source, headers, parameter_name, combo):
    kind = source["kind"]
    if kind == "staticList":
        return list(source["values"])
    if kind == "range":
        range_type = source["type"]
        if range_type == "IsoWeek":
            return _iso_week_range(source["from"], source["to"], source.get("format", _DEFAULT_ISO_WEEK_FORMAT))
        if range_type == "Date":
            return _date_range(source["from"], source["to"], source.get("format", _DEFAULT_DATE_FORMAT))
        return _number_range(source["from"], source["to"])
    if kind == "discovery":
        url_template = _substitute_known_parameters(source["urlTemplate"], combo)
        response = _checked_request("Discovery request", url_template, lambda: requests.get(url_template, headers=headers, timeout=10))
        _require_ok("Discovery request", url_template, response)
        items = _resolve_items(_json_or_fail("Discovery request", url_template, response), source["itemsPath"])
        return [str(_resolve_field(item, source["valuePath"])) for item in items]
    if kind == "browserDiscovery":
        return _resolve_browser_discovery(source, headers, parameter_name, combo)
    raise ValueError(f"Unknown parameter source: {kind}")


# Best-effort: every ApiParameterSource value is a plain string end to end
# (see _resolve_parameter_values above), so a body variable bound to a
# Number/Boolean parameter needs converting before it fits a strictly-typed
# request body (e.g. a GraphQL server rejecting a stringified number). An
# unparsable value falls back to the raw string rather than raising — a
# strictly-typed target server rejecting it is then a target-site problem
# this can only mitigate, not fully solve (see ApiBodyVariable.CoerceTo).
def _coerce_body_value(value, coerce_to):
    if coerce_to == "Number":
        try:
            return float(value) if "." in value else int(value)
        except ValueError:
            return value
    if coerce_to == "Boolean":
        return value.strip().lower() in ("true", "1", "yes")
    return value


# Renders BODY (Issue #55's request-body tree) into a plain JSON-able Python
# value for one already-resolved parameter combo — an object/array node just
# recurses over its own children, a variable node looks its current value up
# in combo (optionally coerced), and a literal node returns its fixed value
# (kind == "Null" is the one case with no "value" key to read at all, see
# PythonApiConfigLiteral.RenderBody).
def _render_body(node, combo):
    if node is None:
        return None
    if "properties" in node:
        return {key: _render_body(child, combo) for key, child in node["properties"].items()}
    if "items" in node:
        return [_render_body(item, combo) for item in node["items"]]
    if "parameterName" in node:
        return _coerce_body_value(combo[node["parameterName"]], node.get("coerceTo"))
    kind = node["kind"]
    return None if kind == "Null" else node["value"]




# Walks the API-Mode tree at runtime: a group node ("children" in node)
# resolves its path against `scope` (N instances if the result is a JSON
# array, at most 1 otherwise — see ApiGroup's doc comment on why this is
# inferred rather than an explicit flag like Container-Mode's "repeating")
# and recurses into each instance; a field leaf reads a single value from
# `scope` directly. One function handles any nesting depth without the
# template needing to mirror the tree structure — the same pattern
# extract_group() already uses for Container-Mode's CSS-selector tree.
def _extract_api_group(scope, node, siblings=None):
    if "children" in node:
        instances = _resolve_items(scope, node["path"])
        elements = []
        for instance in instances:
            el = ET.Element(node["name"])
            # Issue #206: el is this group instance's own in-construction
            # element — see scraper_grouped.py.j2's own identical doc
            # comment on this same pattern.
            for child in node["children"]:
                result = _extract_api_group(instance, child, el)
                if isinstance(result, list):
                    el.extend(result)
                else:
                    el.append(result)
            elements.append(el)
        return elements

    el = ET.Element(node["name"])
    # Issue #206 follow-up: a derived (combineFields/splitField) field has
    # no path of its own — _resolve_json_path("") would otherwise resolve to
    # the whole scope object rather than "nothing found", so this is
    # guarded explicitly rather than relying on that coincidence. The
    # transform chain still always runs (its own combine/split branch
    # ignores the "" passed here and reads siblings instead), unlike the
    # ordinary "path resolved to nothing" case just below.
    if not node["path"]:
        el.text = _apply_transforms("", node["transform"], siblings)
        return el
    value = _resolve_field(scope, node["path"])
    el.text = "" if value is None else _apply_transforms(str(value), node["transform"], siblings)
    return el








# Sends ONE request (page) and returns (parsed JSON, response), or
# (None, None) when the endpoint answers 404 (see below). Factored out of
# scrape() (Issue #224) so the same code serves a plain single request and
# every page of a cursor/Link-header chain; the response is handed back for
# the Link header (Issue #321).
def _fetch_page_data(url, body, headers):
    if METHOD == "POST":
        response = _checked_request("Request", url, lambda: requests.post(url, headers=headers, json=body, timeout=10))
    else:
        response = _checked_request("Request", url, lambda: requests.get(url, headers=headers, timeout=10))
    # A 404 is treated as "this combination doesn't exist" and skipped
    # rather than aborting the whole run — Api-Mode tries the full
    # cartesian product of every parameter's values without knowing
    # which combinations are actually valid on the target site (no way
    # to express e.g. "this category has no offers for that week"), so
    # hitting at least one missing combination is expected, not
    # exceptional. Every other error status still aborts immediately —
    # unlike a 404, those more likely mean something is actually wrong
    # (bad auth, server error), and silently skipping them could hide a
    # real problem behind an incomplete but "successful"-looking result.
    # If every combination fails (or nothing was ever valid), the
    # existing "at least one output row" check in PythonScriptVerifier
    # still catches that — this doesn't need to track failures itself.
    if response.status_code == 404:
        print(f"Skipped (404 Not Found): {url}")
        return None, None
    _require_ok("Request", url, response)
    data = _json_or_fail("Request", url, response)
    return data, response


def _fetch_pages(url, body, headers):
    data, _ = _fetch_page_data(url, body, headers)
    if data is not None:
        yield data


def scrape():
    headers = _build_headers()
    combos = _resolve_parameter_combos(headers)

    # Multiple root groups (and/or multiple parameter combinations, each its
    # own request) are siblings in GROUPS/across requests, but XML needs
    # exactly one root element — wrap them all in a single <Ergebnis>
    # element, same as Container-Mode.
    root = ET.Element("Ergebnis")
    blueprint_rows = []
    blueprint_tree_elements = []
    for combo in combos:
        # Every parameter value is URL-encoded before being substituted into
        # UrlTemplate — values discovered at runtime (DiscoverySource) could
        # contain spaces or other characters that aren't valid unescaped in a
        # URL.
        encoded_combo = {name: quote(str(value), safe="") for name, value in combo.items()}
        url = URL_TEMPLATE.format(**encoded_combo)

        body = _render_body(BODY, combo)
        for data in _fetch_pages(url, body, headers):
            for node in GROUPS:
                for el in _extract_api_group(data, node):
                    root.append(el)
    return root, blueprint_rows, blueprint_tree_elements





# Issue #291: the XML 1.0 spec only allows tab, LF, CR and characters from
# U+0020 on (minus the surrogate range and U+FFFE/U+FFFF) — a control character
# such as the BEL (U+0007) is illegal even as a character reference, so there
# is no way to write it. Python's xml.etree.ElementTree does not check that and
# would serialize it raw, producing a file no conforming XML parser accepts
# (the companion's own trial-run check included). Such characters are removed
# from every element's text right before the tree is written as XML; JSON and
# CSV output don't need this (json.dump escapes them, CSV has no restriction).
_ILLEGAL_XML_CHARS_RE = re.compile("[\x00-\x08\x0b\x0c\x0e-\x1f\ud800-\udfff￾￿]")


def _strip_illegal_xml_chars(root):
    for element in root.iter():
        if element.text:
            element.text = _ILLEGAL_XML_CHARS_RE.sub("", element.text)
        if element.tail:
            element.tail = _ILLEGAL_XML_CHARS_RE.sub("", element.tail)


def main():
    root, blueprint_rows, blueprint_tree_elements = scrape()
    output_root = _tree_without_hidden_fields(root)
    tree = ET.ElementTree(output_root)
    _strip_illegal_xml_chars(tree.getroot())
    ET.indent(tree)
    tree.write(OUTPUT_PATH, encoding="utf-8", xml_declaration=True)
    count = len(root.findall(".//*"))
    print(f"Done — {count} elements written to {OUTPUT_PATH}")


if __name__ == "__main__":
    main()
